class Solution {
  public int catMouseGame(int[][] graph) {
    int n = graph.length;
    int[][][] color = new int[n][n][2], degree = new int[n][n][2];
    java.util.ArrayDeque<int[]> q = new java.util.ArrayDeque<>();
    for (int m = 0; m < n; m++)
      for (int c = 0; c < n; c++)
        for (int t = 0; t < 2; t++)
          degree[m][c][t] =
              t == 0 ? graph[m].length : graph[c].length - (contains(graph[c], 0) ? 1 : 0);
    for (int c = 1; c < n; c++) {
      color[0][c][0] = 1;
      q.add(new int[] {0, c, 0, 1});
      color[c][c][0] = 2;
      q.add(new int[] {c, c, 0, 2});
      color[c][c][1] = 2;
      q.add(new int[] {c, c, 1, 2});
    }
    while (!q.isEmpty()) {
      int[] z = q.poll();
      int m = z[0], c = z[1], t = z[2], w = z[3];
      for (int[] p : parents(graph, m, c, t)) {
        int pm = p[0], pc = p[1], pt = p[2];
        if (color[pm][pc][pt] != 0) continue;
        if ((pt == 0 && w == 1) || (pt == 1 && w == 2)) {
          color[pm][pc][pt] = w;
          q.add(new int[] {pm, pc, pt, w});
        } else if (--degree[pm][pc][pt] == 0) {
          color[pm][pc][pt] = w;
          q.add(new int[] {pm, pc, pt, w});
        }
      }
    }
    return color[1][2][0];
  }

  boolean contains(int[] a, int x) {
    for (int v : a) if (v == x) return true;
    return false;
  }

  java.util.List<int[]> parents(int[][] g, int m, int c, int t) {
    java.util.List<int[]> r = new java.util.ArrayList<>();
    if (t == 0) {
      for (int pc : g[c]) if (pc != 0) r.add(new int[] {m, pc, 1});
    } else for (int pm : g[m]) r.add(new int[] {pm, c, 0});
    return r;
  }
}
